SET DEFINE OFF

-- Disable appointment triggers while loading (audit history is inserted explicitly)
BEGIN
    FOR t IN (SELECT trigger_name FROM user_triggers WHERE table_name = 'APPOINTMENT') LOOP
        EXECUTE IMMEDIATE 'ALTER TRIGGER ' || t.trigger_name || ' DISABLE';
    END LOOP;
END;
/

-- Clear existing data (child tables first)
DELETE FROM appointment_audit;
DELETE FROM payment;
DELETE FROM prescription_item;
DELETE FROM consultation;
DELETE FROM appointment;
DELETE FROM patient;
DELETE FROM doctor_schedule;
DELETE FROM hospital;
DELETE FROM doctor;
DELETE FROM specialization;

