-- Move identity columns past the explicitly inserted IDs
ALTER TABLE specialization MODIFY specialization_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE hospital MODIFY hospital_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE doctor MODIFY doctor_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE doctor_schedule MODIFY schedule_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE patient MODIFY patient_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE appointment MODIFY appointment_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE consultation MODIFY consultation_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE prescription_item MODIFY item_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE payment MODIFY payment_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE appointment_audit MODIFY audit_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

COMMIT;

BEGIN
    FOR t IN (SELECT trigger_name FROM user_triggers WHERE table_name = 'APPOINTMENT') LOOP
        EXECUTE IMMEDIATE 'ALTER TRIGGER ' || t.trigger_name || ' ENABLE';
    END LOOP;
END;
/
